-- The MVP's demo careers (owner, 2026-11-18): for each, two of its USP course's 1st-term mandatory subjects, whose
-- Conteúdo Programático feeds the gamified exercises. Each url carries the course (codcur, codhab) the subject is
-- linked to. Picked by hand: the subject that most defines the profession and a hands-on one.
-- shortcut: EAE1101 Princípios de Microeconomia publishes no topics, so Economia uses EAC0111 instead.
insert into public.sources (adapter, url, label, refresh_interval)
select 'usp_discipline', url, 'USP JupiterWeb, disciplina ' || substring(url from 'sgldis=([A-Z0-9]+)') || ' (' || career || ')',
  interval '1 year'
from (values
